 Image image{2,2,Bytes(16,255)};std::array<std::array<double,3>,4>quad{{{0,0,1},{4,0,1},{4,4,1},{0,4,1}}};std::vector<double>depth(16,2);std::vector<uint32_t>pixels(16,0xff123456);rasterHud(image,quad,4,4,depth,pixels);require(std::all_of(pixels.begin(),pixels.end(),[](uint32_t p){return p==0xff123456;}),"HUD leaked through car depth");std::fill(depth.begin(),depth.end(),0);rasterHud(image,quad,4,4,depth,pixels);require(std::all_of(pixels.begin(),pixels.end(),[](uint32_t p){return p==0xffffffff;}),"Visible HUD not rasterized");std::fill(image.pixels.begin(),image.pixels.end(),0);auto previous=pixels;rasterHud(image,quad,4,4,depth,pixels);require(pixels==previous,"Transparent HUD changed image");std::cout<<"PASS HUD depth rejection, visibility and alpha\n";
